<?php declare(strict_types=1); ?>
<section class="view hidden" id="view-event-details" data-title="Event details" data-section="Student workspace">
  <button class="back-link" data-view="events">← Back to events</button>
  <?php if ($selectedEvent === null): ?>
    <div class="panel empty-state"><h2>Event not found</h2><p class="muted">The requested event does not exist or is no longer available.</p></div>
  <?php else: $tone = event_tone((string) $selectedEvent['club_category']); $dateTimestamp = strtotime((string) $selectedEvent['event_date']); ?>
    <div class="event-detail-banner banner-<?= e($tone) ?>"><div><span><?= e(strtoupper(date('F j, Y', $dateTimestamp))) ?></span><h1><?= e($selectedEvent['title']) ?></h1><p>Presented by <?= e($selectedEvent['club_name']) ?></p></div><span class="large-event-icon">✦</span></div>
    <div class="detail-columns event-detail-columns"><article class="panel"><span class="tag tag-<?= e($tone) ?>"><?= e($selectedEvent['club_category']) ?></span><h2><?= e($selectedEvent['title']) ?></h2><p><?= e($selectedEvent['description']) ?></p><div class="info-grid"><span>◷ <strong><?= e(date('g:i A', strtotime((string) $selectedEvent['event_time']))) ?><?= $selectedEvent['event_end_time'] ? ' · ' . e(date('g:i A', strtotime((string) $selectedEvent['event_end_time']))) : '' ?></strong><small><?= e(date('l, F j', $dateTimestamp)) ?></small></span><span>⌖ <strong><?= e($selectedEvent['venue']) ?></strong><small><?= e($selectedEvent['club_name']) ?></small></span><span>♧ <strong>Capacity <?= e($selectedEvent['capacity']) ?></strong><small><?= e(ucfirst((string) $selectedEvent['status'])) ?></small></span></div></article><aside class="panel registration-card"><h2><?= ($currentUser['role'] ?? null) === 'student' ? 'Your registration' : 'Event information' ?></h2><?php if (($currentUser['role'] ?? null) !== 'student'): ?><p class="muted">This page is read-only for administrators.</p><?php elseif ($selectedEventRegistrationStatus === 'registered'): ?><p class="muted">You are registered for this event.</p><form method="post" action="index.php?action=cancel-registration"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><input type="hidden" name="id" value="<?= (int) $selectedEvent['event_id'] ?>"><button class="button button-outline full-width" type="submit">Cancel registration</button></form><?php elseif ($selectedEventRegistrationStatus === 'attended'): ?><p class="muted">You attended this event.</p><?php elseif ($selectedEventRegistrationStatus === 'cancelled'): ?><p class="muted">Your previous registration was cancelled.</p><form method="post" action="index.php?action=register-event"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><input type="hidden" name="id" value="<?= (int) $selectedEvent['event_id'] ?>"><button class="button button-primary full-width" type="submit">Register again</button></form><?php else: ?><p class="muted">Reserve your place at this event.</p><form method="post" action="index.php?action=register-event"><input type="hidden" name="_csrf" value="<?= e(\ClubConnect\Config\Csrf::token()) ?>"><input type="hidden" name="id" value="<?= (int) $selectedEvent['event_id'] ?>"><button class="button button-primary full-width" type="submit">Register for event</button></form><?php endif; ?></aside></div>
  <?php endif; ?>
</section>
